	if !errors.Is(err, ErrInvalidRun) {
		t.Fatalf("want ErrInvalidRun, got %v", err)
	}

	rec, err := CoordinateAndReceipt(RunRequest{TenantID: "t1", RunID: "r1", Input: "audit"}, "c1", func(in string) (string, error) {
